def comps(g):
    H=len(g);W=len(g[0]);seen=[[False]*W for _ in range(H)];out=[]
    for i in range(H):
        for j in range(W):
            if g[i][j]!=0 and not seen[i][j]:
                col=g[i][j];st=[(i,j)];cells=set();cs=[]
                while st:
                    r,c=st.pop()
                    if(r,c) in cells:continue
                    cells.add((r,c));cs.append((r,c))
                    for dr in(-1,0,1):
                        for dc in(-1,0,1):
                            nr,nc=r+dr,c+dc
                            if 0<=nr<H and 0<=nc<W and g[nr][nc]==col and not ((nr,nc) in cells):
                                st.append((nr,nc))
                out.append((col,cells))
    return out

