import numpy as np
from scipy import ndimage

def comps(g):
    m=np.array(g); lab,n=ndimage.label(m!=0, structure=np.ones((3,3)))
    out=[]
    for i in range(1,n+1):
        ys,xs=np.where(lab==i)
        cells=[(y,x,int(m[y,x])) for y,x in zip(ys,xs)]
        ys0=min(y for y,x,c in cells); xs0=min(x for y,x,c in cells)
        h=max(y for y,x,c in cells)-ys0+1; w=max(x for y,x,c in cells)-xs0+1
        out.append(dict(cells=cells, ys0=ys0, xs0=xs0, h=h, w=w, n=len(cells)))
    return out

def bar_specs(out_g):
    g=np.array(out_g); res={}
    for r in range(len(g)):
        row=g[r]; nz=[c for c,v in enumerate(row) if v]
        if not nz: continue
        cols=set(nz)
        # horizontal run containing... simplify: record runs
        runs=[]; cur=[nz[0]]
        for c in nz[1:]:
            if c==cur[-1]+1: cur.append(c)
            else: runs.append((min(cur),max(cur))); cur=[c]
        runs.append((min(cur),max(cur)))
        for c0,c1 in runs:
            color=g[r][c0]
            key=(color,r,c0,c1)
            res.setdefault(color,[]).append((r,c0,c1,len(runs)))
    return res

