        arr=np.array(gin)[sh['ys0']:sh['ys0']+sh['h'], sh['xs0']:sh['xs0']+sh['w']]
        longest_h=max(max((np.argmax((arr[y]==arr[y][c] if False else True))) for c in [0]),[np.max(np.where(arr[y]==arr[0,0]))[1]+1 if False else 0])
        # simpler: per-row max run of same color as object
        lh=lv=0; best=0
        for y in range(sh['h']):
            row=arr[y]; cur=0; b=0
            for x in range(1,sh['w']):
                if row[x]==row[x-1]: cur+=1
                else: cur=1
                b=max(b,cur)
            lh=max(lh,b)
        for x in range(sh['w']):
            col=[arr[y][x] for y in range(sh['h'])]
            cur=0; b=0
            for y in range(1,sh['h']):
                if col[y]==col[y-1]: cur+=1
                else: cur=1
                b=max(b,cur)
            lv=max(lv,b)
        res[i]=dict(n=sh['n'],h=sh['h'],w=sh['w'],lh=lh,lv=lv,rc=tuple(int((arr[y]==arr[y][0]).sum()) for y in range(sh['h'])),cc=(min(x for _,x,c in sh['cells']),max(x for _,x,c in sh['cells'])))
    return res
