import numpy as np
from collections import defaultdict, Counter

def comps_of(g, val):
    H=len(g); W=len(g[0]); seen=set(); res=[]
    for r in range(H):
        for c in range(W):
            if g[r][c]==val and (r,c) not in seen:
                stack=[(r,c)]; cells=[]
                while stack:
                    y,x=stack.pop()
                    if (y,x) in seen: continue
                    seen.add((y,x)); cells.append((y,x))
                    for dy,dx in [(1,0),(-1,0),(0,1),(0,-1)]:
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and g[ny][nx]==val and (ny,nx) not in seen:
                            stack.append((ny,nx))
                res.append(cells)
    return res

def feats(cells):
    ys=[y for y,_ in cells]; xs=[x for _,x in cells]
    h=max(ys)-min(ys)+1; w=max(xs)-min(xs)+1
    def maxrun(ax):
        # max length of contiguous run along axis ax (rows->horizontal runs)
        arr=[[1 if (y,x) in set(cells) else 0 for x in range(min(xs),max(xs)+1)] for y in range(min(ys),max(ys)+1)]
        if ax=='h':
            best=0
            for row in arr:
                L=0; prev=False
                for v in row:
                    if v and not prev: L+=1
                    elif not v: L=0
                    prev = v
                    best=max(best,L)
            return best
        else:
            best=0
            for col in zip(*arr):
                L=0; prev=False
                for v in col:
                    if v and not prev: L+=1
                    elif not v: L=0
                    prev=v
                    best=max(best,L)
            return best
    hr=maxrun('h'); vr=maxrun('v')
    return dict(n=len(cells), h=hr, v=vr, orient='V' if vr>hr else 'H',
                top=min(ys), left=min(xs), bot=max(ys), right=max(xs))

